<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/auth.php';require_page('encounters.php');
$page_title='SOAP / EMR';$page_subtitle=is_role('doctor')?'Clinical documentation: tulis SOAP, simpan draft, finalisasi dan buat addendum bila catatan sudah signed.':'Rekam medis elektronik untuk review sesuai kewenangan role.';$msg='';$did=doctor_id($pdo);
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';
 if($action==='create' && is_role('doctor')){
   $app=(int)($_POST['appointment_id']??0);$s=$pdo->prepare("SELECT a.id,a.patient_id FROM appointments a WHERE a.id=? AND a.doctor_id=? LIMIT 1");$s->execute([$app,$did]);$a=$s->fetch();
   if(!$a){$msg='Appointment tidak ditemukan atau bukan jadwal Anda.';} else {$s=$pdo->prepare('SELECT COUNT(*) FROM encounters WHERE appointment_id=?');$s->execute([$app]); if((int)$s->fetchColumn()>0){$msg='Appointment tersebut sudah memiliki encounter.';}else{$s=$pdo->prepare('INSERT INTO encounters(appointment_id,patient_id,doctor_id,clinical_status) VALUES(?,?,?,\'draft\')');$s->execute([$app,$a['patient_id'],$did]);$eid=(int)$pdo->lastInsertId();audit($pdo,'CREATE','ENCOUNTER',$eid,'Clinical encounter dibuat oleh dokter.');redirect('encounters.php?id='.$eid);}} }
 elseif($action==='save' && is_role('doctor')){
   $id=(int)$_POST['id'];$s=$pdo->prepare('SELECT * FROM encounters WHERE id=? AND doctor_id=? LIMIT 1');$s->execute([$id,$did]);$e=$s->fetch(); if(!$e){deny_access('Encounter ini bukan bagian dari layanan dokter Anda.');}
   if($e['clinical_status']==='signed' || $e['clinical_status']==='amended'){$msg='SOAP yang sudah ditandatangani bersifat terkunci. Gunakan Addendum untuk koreksi/penambahan. ';}
   else{$s=$pdo->prepare('UPDATE encounters SET chief_complaint=?,subjective=?,objective=?,assessment=?,plan=?,diagnosis_code=?,diagnosis_name=?,allergies=?,clinical_status=\'draft\' WHERE id=?');$s->execute([trim($_POST['chief_complaint']),trim($_POST['subjective']),trim($_POST['objective']),trim($_POST['assessment']),trim($_POST['plan']),trim($_POST['diagnosis_code']),trim($_POST['diagnosis_name']),trim($_POST['allergies']),$id]);audit($pdo,'UPDATE','ENCOUNTER',$id,'Draft SOAP diperbarui oleh dokter.');$msg='Draft SOAP tersimpan.';}
 }
 elseif($action==='sign' && is_role('doctor')){
   $id=(int)$_POST['id'];$s=$pdo->prepare('SELECT * FROM encounters WHERE id=? AND doctor_id=? LIMIT 1');$s->execute([$id,$did]);$e=$s->fetch();if(!$e){deny_access('Encounter ini bukan bagian dari layanan dokter Anda.');}
   if($e['clinical_status']==='signed' || $e['clinical_status']==='amended'){$msg='SOAP sudah final.';}else{$s=$pdo->prepare('UPDATE encounters SET chief_complaint=?,subjective=?,objective=?,assessment=?,plan=?,diagnosis_code=?,diagnosis_name=?,allergies=?,clinical_status=\'signed\',signed_at=NOW() WHERE id=?');$s->execute([trim($_POST['chief_complaint']),trim($_POST['subjective']),trim($_POST['objective']),trim($_POST['assessment']),trim($_POST['plan']),trim($_POST['diagnosis_code']),trim($_POST['diagnosis_name']),trim($_POST['allergies']),$id]);audit($pdo,'SIGN','ENCOUNTER',$id,'SOAP difinalisasi dan ditandatangani oleh dokter.');$msg='SOAP berhasil difinalisasi dan ditandatangani.';}
 }
 elseif($action==='addendum' && is_role('doctor')){
   $id=(int)$_POST['id'];$note=trim($_POST['addendum']??'');$s=$pdo->prepare("SELECT id,clinical_status FROM encounters WHERE id=? AND doctor_id=? LIMIT 1");$s->execute([$id,$did]);$e=$s->fetch();if(!$e){deny_access();}if($e['clinical_status']!=='signed'&&$e['clinical_status']!=='amended'){$msg='Addendum digunakan setelah SOAP ditandatangani.';}elseif($note===''){$msg='Isi addendum belum boleh kosong.';}else{$s=$pdo->prepare('INSERT INTO encounter_addenda(encounter_id,author_user_id,note) VALUES(?,?,?)');$s->execute([$id,current_user_id(),$note]);$pdo->prepare("UPDATE encounters SET clinical_status='amended' WHERE id=?")->execute([$id]);audit($pdo,'ADDENDUM','ENCOUNTER',$id,'Addendum SOAP ditambahkan oleh dokter.');$msg='Addendum berhasil dicatat tanpa mengubah SOAP asli.';}
 }
}
$appointments=[];if(is_role('doctor')){$s=$pdo->prepare("SELECT a.id,a.appointment_date,a.queue_no,p.name,p.mrn FROM appointments a JOIN patients p ON p.id=a.patient_id LEFT JOIN encounters e ON e.appointment_id=a.id WHERE a.doctor_id=? AND e.id IS NULL AND a.status NOT IN ('cancelled','no_show') ORDER BY a.appointment_date DESC");$s->execute([$did]);$appointments=$s->fetchAll();}
$where='';$params=[];if(is_role('doctor')){$where='WHERE e.doctor_id=?';$params=[$did];}elseif(is_role('nurse')){$where='WHERE EXISTS(SELECT 1 FROM nursing_notes n WHERE n.encounter_id=e.id AND n.nurse_id=? ) OR EXISTS(SELECT 1 FROM appointments a WHERE a.id=e.appointment_id AND a.appointment_date>=DATE_SUB(NOW(),INTERVAL 24 HOUR))';$params=[current_user_id()];}
$sql="SELECT e.*,p.name patient,p.mrn,u.name doctor FROM encounters e JOIN patients p ON p.id=e.patient_id JOIN doctors d ON d.id=e.doctor_id JOIN users u ON u.id=d.user_id $where ORDER BY e.encounter_date DESC";$s=$pdo->prepare($sql);$s->execute($params);$list=$s->fetchAll();
$id=(int)($_GET['id']??0);$e=null;$addenda=[];if($id){$sql="SELECT e.*,p.name patient,p.mrn,u.name doctor FROM encounters e JOIN patients p ON p.id=e.patient_id JOIN doctors d ON d.id=e.doctor_id JOIN users u ON u.id=d.user_id WHERE e.id=?";$par=[$id];if(is_role('doctor')){$sql.=' AND e.doctor_id=?';$par[]=$did;}$s=$pdo->prepare($sql);$s->execute($par);$e=$s->fetch();if($e){$s=$pdo->prepare("SELECT a.*,u.name author FROM encounter_addenda a JOIN users u ON u.id=a.author_user_id WHERE a.encounter_id=? ORDER BY a.created_at ASC");$s->execute([$id]);$addenda=$s->fetchAll();}}
include __DIR__.'/includes/header.php';?>
<?php if($msg):?><div class="alert <?=str_contains($msg,'berhasil')||str_contains($msg,'tersimpan')?'success':'danger'?>"><?=h($msg)?></div><?php endif;?>
<?php if(is_role('doctor')):?><div class="card"><div class="card-header"><div><h3 class="section-title">Open New Clinical Encounter</h3><p class="section-subtitle">Dokter memilih appointment miliknya yang belum memiliki encounter.</p></div><span class="tag">Physician-owned</span></div><?php if($appointments):?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create"><div style="grid-column:1/-1"><label>Appointment</label><select name="appointment_id" required><option value="">Pilih appointment</option><?php foreach($appointments as $a):?><option value="<?=$a['id']?>">#<?=$a['id']?> · <?=h($a['mrn'].' — '.$a['name'].' · '.date('d/m/Y H:i',strtotime($a['appointment_date'])))?></option><?php endforeach;?></select></div><div><button class="btn primary">+ Buka Encounter & Tulis SOAP</button></div></form><?php else:?><div class="empty"><strong>Tidak ada appointment baru</strong><p>Semua appointment Anda yang relevan sudah memiliki encounter, atau belum ada jadwal.</p></div><?php endif;?></div><div style="height:16px"></div><?php endif;?>
<div class="grid two"><div class="card"><div class="card-header"><div><h3 class="section-title">Encounter List</h3><p class="section-subtitle"><?=count($list)?> catatan dalam cakupan akses Anda.</p></div></div><div class="table-wrap"><table><tr><th>Pasien</th><th>Dokter</th><th>Waktu</th><th>Status</th><th></th></tr><?php foreach($list as $r):?><tr><td><b><?=h($r['patient'])?></b><br><span class="mini"><?=h($r['mrn'])?></span></td><td><?=h($r['doctor'])?></td><td><?=h(date('d/m/Y H:i',strtotime($r['encounter_date'])))?></td><td><span class="badge <?=$r['clinical_status']==='draft'?'warn':($r['clinical_status']==='amended'?'info':'ok')?>"><?=h(strtoupper($r['clinical_status']))?></span></td><td><a class="table-link" href="encounters.php?id=<?=$r['id']?>">Buka</a></td></tr><?php endforeach;?></table></div></div>
<div class="card"><?php if(!$e):?><div class="empty"><strong>Pilih encounter</strong><p>Dokter dapat membuka encounter miliknya. Perawat dan Rekam Medis dapat review sesuai kewenangan.</p></div><?php else:?><div class="card-header"><div><h3 class="section-title">SOAP — <?=h($e['patient'])?></h3><p class="section-subtitle"><?=h($e['mrn'])?> · <?=h($e['doctor'])?> · <?=h(date('d M Y H:i',strtotime($e['encounter_date'])))?></p></div><span class="badge <?=$e['clinical_status']==='draft'?'warn':($e['clinical_status']==='amended'?'info':'ok')?>"><?=h(strtoupper($e['clinical_status']))?></span></div>
<?php if(is_role('doctor') && (int)$e['doctor_id']===$did && !in_array($e['clinical_status'],['signed','amended'],true)):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=$e['id']?>"><div class="soap-grid"><div class="soap-box"><h4>CC — Chief Complaint</h4><textarea name="chief_complaint" required><?=h($e['chief_complaint'])?></textarea></div><div class="soap-box"><h4>S — Subjective</h4><textarea name="subjective" required><?=h($e['subjective'])?></textarea></div><div class="soap-box"><h4>O — Objective</h4><textarea name="objective" required><?=h($e['objective'])?></textarea></div><div class="soap-box"><h4>A — Assessment</h4><textarea name="assessment" required><?=h($e['assessment'])?></textarea></div><div class="soap-box"><h4>P — Plan</h4><textarea name="plan" required><?=h($e['plan'])?></textarea></div><div class="soap-box"><h4>Diagnosis & Allergy</h4><div class="form-grid"><input name="diagnosis_code" value="<?=h($e['diagnosis_code'])?>" placeholder="ICD-10"><input name="diagnosis_name" value="<?=h($e['diagnosis_name'])?>" placeholder="Diagnosis"></div><br><label>Alergi</label><input name="allergies" value="<?=h($e['allergies'])?>" placeholder="NKDA / alergi obat / makanan"></div></div><div class="section-actions" style="margin-top:13px"><button class="btn secondary" name="action" value="save">Simpan Draft</button><button class="btn primary" name="action" value="sign">✓ Finalisasi & Tanda Tangan</button></div></form>
<?php else:?><div class="soap-grid"><?php foreach(['CC — Chief Complaint'=>'chief_complaint','S — Subjective'=>'subjective','O — Objective'=>'objective','A — Assessment'=>'assessment','P — Plan'=>'plan','Diagnosis'=>'diagnosis_name','Allergies'=>'allergies'] as $k=>$v):?><div class="soap-box"><h4><?=h($k)?></h4><div><?=nl2br(h($e[$v]?:'Belum diisi'))?></div></div><?php endforeach;?></div><?php if($e['signed_at']):?><div class="notice" style="margin-top:14px"><div>✓</div><div><strong>Signed clinical note</strong><span>SOAP final pada <?=h(date('d/m/Y H:i',strtotime($e['signed_at'])))?>. Catatan asli terkunci; koreksi dilakukan melalui addendum.</span></div></div><?php endif;?><?php endif;?>
<?php if(is_role('doctor') && (int)$e['doctor_id']===$did && in_array($e['clinical_status'],['signed','amended'],true)):?><div style="height:14px"></div><div class="card" style="background:#fafafa"><div class="card-header"><div><h3 class="section-title">Addendum</h3><p class="section-subtitle">Tambahkan informasi tanpa mengubah SOAP asli yang sudah signed.</p></div></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="addendum"><input type="hidden" name="id" value="<?=$e['id']?>"><textarea name="addendum" required placeholder="Contoh: hasil pemeriksaan terbaru / klarifikasi / koreksi administratif klinis"></textarea><button class="btn secondary" style="margin-top:10px">+ Simpan Addendum</button></form></div><?php endif;?>
<?php if($addenda):?><div style="height:14px"></div><div class="card"><h3 class="section-title">Addendum History</h3><?php foreach($addenda as $a):?><div class="timeline-item"><strong><?=h($a['author'])?></strong><div class="mini"><?=h(date('d/m/Y H:i',strtotime($a['created_at'])))?></div><p><?=nl2br(h($a['note']))?></p></div><?php endforeach;?></div><?php endif;?></div><?php endif;?></div></div>
<?php include __DIR__.'/includes/footer.php';?>